// Parse an inbound WhatsApp Cloud API text reply to an appointment message and
// classify it as confirmed / cancelled / reschedule_requested / manual_review,
// using deterministic, word/phrase-aware keyword matching.
//
// This is a REPLY PARSER only -- it does not update any calendar or database,
// does not send any WhatsApp message, and does not claim that an appointment
// was actually changed. It only reports what the customer's reply seems to say.
//
// NOTE: this endpoint is POST-only. It does NOT implement Meta's required GET
// verification handshake or X-Hub-Signature-256 signature validation. Test it
// with any synthetic HTTP client; do not point Meta's webhook config at it
// as-is -- see this workflow's documentation for what a production setup needs.

const item = $input.first().json;
const payload = item.body !== undefined ? item.body : item;

function safeGet(obj, path, fallback) {
  try {
    let cur = obj;
    for (const key of path) {
      if (cur === null || cur === undefined) return fallback;
      cur = cur[key];
    }
    return cur === undefined ? fallback : cur;
  } catch (e) {
    return fallback;
  }
}

// Word/phrase-aware matcher: \b boundaries so "yes" won't match inside
// "yesterday". Multi-word phrases (e.g. "another day") match as a phrase
// with flexible whitespace between words.
function buildMatcher(keyword) {
  const escaped = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = escaped.includes(' ') ? escaped.replace(/ /g, '\\s+') : escaped;
  return new RegExp('\\b' + pattern + '\\b');
}

function matchingCategories(text, keywordMap) {
  const hits = [];
  for (const [category, keywords] of Object.entries(keywordMap)) {
    if (keywords.some((k) => buildMatcher(k).test(text))) hits.push(category);
  }
  return hits;
}

let result;

try {
  if (!payload || typeof payload !== 'object') {
    result = { action: null, messageType: 'malformed', status: 'ignored' };
  } else {
    const entry = safeGet(payload, ['entry', 0], null);
    const change = entry ? safeGet(entry, ['changes', 0], null) : null;
    const value = change ? safeGet(change, ['value'], null) : null;

    if (!value) {
      result = { action: null, messageType: 'malformed', status: 'ignored' };
    } else {
      const messages = Array.isArray(value.messages) ? value.messages : [];
      const statuses = Array.isArray(value.statuses) ? value.statuses : [];

      if (messages.length === 0) {
        if (statuses.length > 0) {
          result = { action: null, messageType: 'status_event', status: 'ignored' };
        } else {
          result = { action: null, messageType: 'malformed', status: 'ignored' };
        }
      } else {
        const firstMessage = messages[0];
        const msgType = firstMessage.type;
        const text = msgType === 'text' ? safeGet(firstMessage, ['text', 'body'], '') : '';

        if (msgType !== 'text' || !text || typeof text !== 'string' || text.trim() === '') {
          result = { action: null, messageType: msgType || 'unknown', status: 'ignored' };
        } else {
          const normalized = text.trim().toLowerCase();

          // Deterministic keyword routing -- not AI/ML. Adapt to your language(s)
          // and vocabulary; this is a starting template, not a finished parser.
          const KEYWORDS = {
            confirmed: ['confirm', 'confirmed', 'confirming', "i'll be there", 'ill be there', 'i will be there', 'count me in', 'yes'],
            cancelled: ['cancel', 'cancelled', 'canceling', 'cancelling', "can't make it", 'cant make it', 'not able to make it'],
            reschedule_requested: ['reschedule', 'move it', 'another day', 'different day', 'different time', 'change the time', 'postpone', 'push back'],
          };

          const hits = matchingCategories(normalized, KEYWORDS);
          // Exactly one category matched -> use it. Zero matches (no signal) or
          // more than one (conflicting signals, e.g. "confirm" and "cancel" both
          // present) -> manual_review is the safe default rather than guessing.
          const action = hits.length === 1 ? hits[0] : 'manual_review';

          result = { action, messageType: 'text', status: 'classified' };
        }
      }
    }
  }
} catch (err) {
  result = { action: null, messageType: 'malformed', status: 'ignored' };
}

return [{ json: result }];
